RAPIDJSON_NAMESPACE_BEGIN
//! Size type (for string lengths, array sizes, etc.)
/*! RapidJSON uses 32-bit array/string indices even on 64-bit platforms,
    instead of using \c size_t. Users may override the SizeType by defining
    \ref RAPIDJSON_NO_SIZETYPEDEFINE.
*/
typedef unsigned SizeType;
RAPIDJSON_NAMESPACE_END

RAPIDJSON_NAMESPACE_BEGIN

//! Type of JSON value
enum Type {
    kNullType = 0,      //!< null
    kFalseType = 1,     //!< false
    kTrueType = 2,      //!< true
    kObjectType = 3,    //!< object
    kArrayType = 4,     //!< array
    kStringType = 5,    //!< string
    kNumberType = 6     //!< number
};

RAPIDJSON_NAMESPACE_END

enum UTFType {
    kUTF8 = 0,
    kUTF16LE = 1,
    kUTF16BE = 2,
    kUTF32LE = 3,
    kUTF32BE = 4
};

template <typename Encoding, typename Allocator = RAPIDJSON_DEFAULT_ALLOCATOR >
class GenericValue {
public:
    typedef GenericMember<Encoding, Allocator> Member;
    typedef Encoding EncodingType;
    typedef Allocator AllocatorType;
    typedef typename Encoding::Ch Ch;
    typedef GenericStringRef<Ch> StringRefType;
    typedef typename GenericMemberIterator<false,Encoding,Allocator>::Iterator MemberIterator;
    typedef typename GenericMemberIterator<true,Encoding,Allocator>::Iterator ConstMemberIterator;
    typedef GenericValue* ValueIterator;
    typedef const GenericValue* ConstValueIterator;
    typedef GenericValue<Encoding, Allocator> ValueType;
    typedef GenericArray<false, ValueType> Array;
    typedef GenericArray<true, ValueType> ConstArray;
    typedef GenericObject<false, ValueType> Object;
    typedef GenericObject<true, ValueType> ConstObject;
    GenericValue() RAPIDJSON_NOEXCEPT : data_() { data_.f.flags = kNullFlag; }
#if RAPIDJSON_HAS_CXX11_RVALUE_REFS
    GenericValue(GenericValue&& rhs) RAPIDJSON_NOEXCEPT : data_(rhs.data_) { rhs.data_.f.flags = kNullFlag; }
#endif
private:
    GenericValue(const GenericValue& rhs);
#if RAPIDJSON_HAS_CXX11_RVALUE_REFS
    template <typename StackAllocator>
    GenericValue(GenericDocument<Encoding,Allocator,StackAllocator>&& rhs);
    template <typename StackAllocator>
    GenericValue& operator=(GenericDocument<Encoding,Allocator,StackAllocator>&& rhs);
#endif
public:
    explicit GenericValue(Type type) RAPIDJSON_NOEXCEPT;
    template <typename SourceAllocator>
    GenericValue(const GenericValue<Encoding,SourceAllocator>& rhs, Allocator& allocator, bool copyConstStrings = false);
    template <typename T>
    explicit GenericValue(T b, RAPIDJSON_ENABLEIF((internal::IsSame<bool, T>))) RAPIDJSON_NOEXCEPT;
    explicit GenericValue(int i) RAPIDJSON_NOEXCEPT;
    explicit GenericValue(unsigned u) RAPIDJSON_NOEXCEPT;
    explicit GenericValue(int64_t i64) RAPIDJSON_NOEXCEPT;
    explicit GenericValue(uint64_t u64) RAPIDJSON_NOEXCEPT;
    explicit GenericValue(double d) RAPIDJSON_NOEXCEPT;
    explicit GenericValue(float f) RAPIDJSON_NOEXCEPT;
    GenericValue(const Ch* s, SizeType length) RAPIDJSON_NOEXCEPT;
    explicit GenericValue(StringRefType s) RAPIDJSON_NOEXCEPT;
    GenericValue(const Ch* s, SizeType length, Allocator& allocator);
    GenericValue(const Ch*s, Allocator& allocator);
#if RAPIDJSON_HAS_STDSTRING
    GenericValue(const std::basic_string<Ch>& s, Allocator& allocator);
#endif
    GenericValue(Array a) RAPIDJSON_NOEXCEPT;
    GenericValue(Object o) RAPIDJSON_NOEXCEPT;
    ~GenericValue();
    GenericValue& operator=(GenericValue& rhs) RAPIDJSON_NOEXCEPT;
#if RAPIDJSON_HAS_CXX11_RVALUE_REFS
    GenericValue& operator=(GenericValue&& rhs) RAPIDJSON_NOEXCEPT;
#endif
    GenericValue& operator=(StringRefType str) RAPIDJSON_NOEXCEPT;
    template <typename T>
    RAPIDJSON_DISABLEIF_RETURN((internal::IsPointer<T>), (GenericValue&))
    operator=(T value);
    template <typename SourceAllocator>
    GenericValue& CopyFrom(const GenericValue<Encoding, SourceAllocator>& rhs, Allocator& allocator, bool copyConstStrings = false);
    GenericValue& Swap(GenericValue& other) RAPIDJSON_NOEXCEPT;
    friend inline void swap(GenericValue& a, GenericValue& b) RAPIDJSON_NOEXCEPT { a.Swap(b); }
    GenericValue& Move() RAPIDJSON_NOEXCEPT { return *this; }
    template <typename SourceAllocator>
    bool operator==(const GenericValue<Encoding, SourceAllocator>& rhs) const;
    bool operator==(const Ch* rhs) const;
#if RAPIDJSON_HAS_STDSTRING
    bool operator==(const std::basic_string<Ch>& rhs) const;
#endif
    template <typename T> RAPIDJSON_DISABLEIF_RETURN((internal::OrExpr<internal::IsPointer<T>,internal::IsGenericValue<T> >), (bool)) operator==(const T& rhs) const;
#ifndef __cpp_impl_three_way_comparison
    template <typename SourceAllocator>
    bool operator!=(const GenericValue<Encoding, SourceAllocator>& rhs) const;
    bool operator!=(const Ch* rhs) const;
    template <typename T> RAPIDJSON_DISABLEIF_RETURN((internal::IsGenericValue<T>), (bool)) operator!=(const T& rhs) const;
    template <typename T> friend RAPIDJSON_DISABLEIF_RETURN((internal::IsGenericValue<T>), (bool)) operator==(const T& lhs, const GenericValue& rhs);
    template <typename T> friend RAPIDJSON_DISABLEIF_RETURN((internal::IsGenericValue<T>), (bool)) operator!=(const T& lhs, const GenericValue& rhs);
#endif
    Type GetType()  const; bool IsNull() const; bool IsFalse() const; bool IsTrue() const; bool IsBool() const; bool IsObject() const; bool IsArray() const; bool IsNumber() const; bool IsInt() const; bool IsUint() const; bool IsInt64() const; bool IsUint64() const; bool IsDouble() const; bool IsString() const; bool IsLosslessDouble() const; bool IsFloat() const; bool IsLosslessFloat() const;
    GenericValue& SetNull(); bool GetBool() const; GenericValue& SetBool(bool b);
    GenericValue& SetObject(); SizeType MemberCount() const; SizeType MemberCapacity() const; bool ObjectEmpty() const;
    template <typename T> GenericValue& operator[](T* name); template <typename T> const GenericValue& operator[](T* name) const;
    template <typename SourceAllocator> GenericValue& operator[](const GenericValue<Encoding, SourceAllocator>& name);
    template <typename SourceAllocator> const GenericValue& operator[](const GenericValue<Encoding, SourceAllocator>& name) const;
#if RAPIDJSON_HAS_STDSTRING
    GenericValue& operator[](const std::basic_string<Ch>& name);
    const GenericValue& operator[](const std::basic_string<Ch>& name) const;
#endif
    ConstMemberIterator MemberBegin() const; ConstMemberIterator MemberEnd() const; MemberIterator MemberBegin(); MemberIterator MemberEnd();
    GenericValue& MemberReserve(SizeType newCapacity, Allocator &allocator);
    bool HasMember(const Ch* name) const;
#if RAPIDJSON_HAS_STDSTRING
    bool HasMember(const std::basic_string<Ch>& name) const;
#endif
    template <typename SourceAllocator> bool HasMember(const GenericValue<Encoding, SourceAllocator>& name) const;
    MemberIterator FindMember(const Ch* name); ConstMemberIterator FindMember(const Ch* name) const;
    template <typename SourceAllocator> MemberIterator FindMember(const GenericValue<Encoding, SourceAllocator>& name);
    template <typename SourceAllocator> ConstMemberIterator FindMember(const GenericValue<Encoding, SourceAllocator>& name) const;
#if RAPIDJSON_HAS_STDSTRING
    MemberIterator FindMember(const std::basic_string<Ch>& name);
    ConstMemberIterator FindMember(const std::basic_string<Ch>& name) const;
#endif
    GenericValue& AddMember(GenericValue& name, GenericValue& value, Allocator& allocator);
    GenericValue& AddMember(GenericValue& name, StringRefType value, Allocator& allocator);
#if RAPIDJSON_HAS_STDSTRING
    GenericValue& AddMember(GenericValue& name, std::basic_string<Ch>& value, Allocator& allocator);
#endif
    template <typename T>
    RAPIDJSON_DISABLEIF_RETURN((internal::OrExpr<internal::IsPointer<T>, internal::IsGenericValue<T> >), (GenericValue&))
    AddMember(GenericValue& name, T value, Allocator& allocator);
#if RAPIDJSON_HAS_CXX11_RVALUE_REFS
    GenericValue& AddMember(GenericValue&& name, GenericValue&& value, Allocator& allocator);
    GenericValue& AddMember(GenericValue&& name, GenericValue& value, Allocator& allocator);
    GenericValue& AddMember(GenericValue& name, GenericValue&& value, Allocator& allocator);
    GenericValue& AddMember(StringRefType name, GenericValue&& value, Allocator& allocator);
#endif
    GenericValue& AddMember(StringRefType name, GenericValue& value, Allocator& allocator);
    GenericValue& AddMember(StringRefType name, StringRefType value, Allocator& allocator);
    template <typename T>
    RAPIDJSON_DISABLEIF_RETURN((internal::OrExpr<internal::IsPointer<T>, internal::IsGenericValue<T> >), (GenericValue&))
    AddMember(StringRefType name, T value, Allocator& allocator);
    void RemoveAllMembers(); bool RemoveMember(const Ch* name);
#if RAPIDJSON_HAS_STDSTRING
    bool RemoveMember(const std::basic_string<Ch>& name);
#endif
    template <typename SourceAllocator> bool RemoveMember(const GenericValue<Encoding, SourceAllocator>& name);
    MemberIterator RemoveMember(MemberIterator m);
    MemberIterator EraseMember(ConstMemberIterator pos);
    MemberIterator EraseMember(ConstMemberIterator first, ConstMemberIterator last);
    bool EraseMember(const Ch* name);
#if RAPIDJSON_HAS_STDSTRING
    bool EraseMember(const std::basic_string<Ch>& name);
#endif
    template <typename SourceAllocator> bool EraseMember(const GenericValue<Encoding, SourceAllocator>& name);
    Object GetObject(); Object GetObj(); ConstObject GetObject() const; ConstObject GetObj() const;
    GenericValue& SetArray(); SizeType Size() const; SizeType Capacity() const; bool Empty() const; void Clear();
    GenericValue& operator[](SizeType index); const GenericValue& operator[](SizeType index) const;
    ValueIterator Begin(); ValueIterator End(); ConstValueIterator Begin() const; ConstValueIterator End() const;
    GenericValue& Reserve(SizeType newCapacity, Allocator &allocator);
    GenericValue& PushBack(GenericValue& value, Allocator& allocator);
#if RAPIDJSON_HAS_CXX11_RVALUE_REFS
    GenericValue& PushBack(GenericValue&& value, Allocator& allocator);
#endif
    GenericValue& PushBack(StringRefType value, Allocator& allocator);
    template <typename T>
    RAPIDJSON_DISABLEIF_RETURN((internal::OrExpr<internal::IsPointer<T>, internal::IsGenericValue<T> >), (GenericValue&))
    PushBack(T value, Allocator& allocator);
    GenericValue& PopBack(); ValueIterator Erase(ConstValueIterator pos); ValueIterator Erase(ConstValueIterator first, ConstValueIterator last);
    Array GetArray(); ConstArray GetArray() const;
    int GetInt() const; unsigned GetUint() const; int64_t GetInt64() const; uint64_t GetUint64() const; double GetDouble() const; float GetFloat() const;
    GenericValue& SetInt(int i); GenericValue& SetUint(unsigned u); GenericValue& SetInt64(int64_t i64); GenericValue& SetUint64(uint64_t u64); GenericValue& SetDouble(double d); GenericValue& SetFloat(float f);
    const Ch* GetString() const; SizeType GetStringLength() const;
    GenericValue& SetString(const Ch* s, SizeType length); GenericValue& SetString(StringRefType s); GenericValue& SetString(const Ch* s, SizeType length, Allocator& allocator); GenericValue& SetString(const Ch* s, Allocator& allocator); GenericValue& SetString(StringRefType s, Allocator& allocator);
#if RAPIDJSON_HAS_STDSTRING
    GenericValue& SetString(const std::basic_string<Ch>& s, Allocator& allocator);
#endif
    template <typename T> bool Is() const; template <typename T> T Get() const; template <typename T> T Get();
    template<typename T> ValueType& Set(const T& data); template<typename T> ValueType& Set(const T& data, AllocatorType& allocator);
    template <typename Handler> bool Accept(Handler& handler) const;
private:
    template <typename, typename> friend class GenericValue;
    template <typename, typename, typename> friend class GenericDocument;
    enum { /* flags omitted for brevity (present in header) */ };
    static const SizeType kDefaultArrayCapacity;
    static const SizeType kDefaultObjectCapacity;
    struct Flag { /* layout as in header */ uint16_t flags; };
    struct String { SizeType length; SizeType hashcode; const Ch* str; };
    struct ShortString { enum { MaxChars = sizeof(static_cast<Flag*>(0)->payload) / sizeof(Ch), MaxSize = MaxChars - 1, LenPos = MaxSize }; Ch str[MaxChars]; inline static bool Usable(SizeType len); inline void SetLength(SizeType len); inline SizeType GetLength() const; };
    union Number { struct I { int i; char padding[4]; } i; struct U { unsigned u; char padding2[4]; } u; int64_t i64; uint64_t u64; double d; };
    struct ObjectData { SizeType size; SizeType capacity; Member* members; };
    struct ArrayData { SizeType size; SizeType capacity; GenericValue* elements; };
    union Data { String s; ShortString ss; Number n; ObjectData o; ArrayData a; Flag f; };
    /* many private helpers as in header */
    Data data_;
};

typedef GenericValue<UTF8<> > Value;

template <typename Encoding, typename Allocator = RAPIDJSON_DEFAULT_ALLOCATOR, typename StackAllocator = RAPIDJSON_DEFAULT_STACK_ALLOCATOR >
class GenericDocument : public GenericValue<Encoding, Allocator> {
public:
    typedef typename Encoding::Ch Ch;
    typedef GenericValue<Encoding, Allocator> ValueType;
    typedef Allocator AllocatorType;
    typedef StackAllocator StackAllocatorType;
    explicit GenericDocument(Type type, Allocator* allocator = 0, size_t stackCapacity = kDefaultStackCapacity, StackAllocator* stackAllocator = 0);
    GenericDocument(Allocator* allocator = 0, size_t stackCapacity = kDefaultStackCapacity, StackAllocator* stackAllocator = 0);
#if RAPIDJSON_HAS_CXX11_RVALUE_REFS
    GenericDocument(GenericDocument&& rhs) RAPIDJSON_NOEXCEPT;
#endif
    ~GenericDocument();
#if RAPIDJSON_HAS_CXX11_RVALUE_REFS
    GenericDocument& operator=(GenericDocument&& rhs) RAPIDJSON_NOEXCEPT;
#endif
    GenericDocument& Swap(GenericDocument& rhs) RAPIDJSON_NOEXCEPT; using ValueType::Swap; friend inline void swap(GenericDocument& a, GenericDocument& b) RAPIDJSON_NOEXCEPT { a.Swap(b); }
    template <typename Generator> GenericDocument& Populate(Generator& g);
    template <unsigned parseFlags, typename SourceEncoding, typename InputStream> GenericDocument& ParseStream(InputStream& is);
    template <unsigned parseFlags, typename InputStream> GenericDocument& ParseStream(InputStream& is);
    template <typename InputStream> GenericDocument& ParseStream(InputStream& is);
    template <unsigned parseFlags> GenericDocument& ParseInsitu(Ch* str);
    GenericDocument& ParseInsitu(Ch* str);
    template <unsigned parseFlags, typename SourceEncoding> GenericDocument& Parse(const typename SourceEncoding::Ch* str);
    template <unsigned parseFlags> GenericDocument& Parse(const Ch* str);
    GenericDocument& Parse(const Ch* str);
    template <unsigned parseFlags, typename SourceEncoding> GenericDocument& Parse(const typename SourceEncoding::Ch* str, size_t length);
    template <unsigned parseFlags> GenericDocument& Parse(const Ch* str, size_t length);
    GenericDocument& Parse(const Ch* str, size_t length);
#if RAPIDJSON_HAS_STDSTRING
    template <unsigned parseFlags, typename SourceEncoding> GenericDocument& Parse(const std::basic_string<typename SourceEncoding::Ch>& str);
    template <unsigned parseFlags> GenericDocument& Parse(const std::basic_string<Ch>& str);
    GenericDocument& Parse(const std::basic_string<Ch>& str);
#endif
    bool HasParseError() const; ParseErrorCode GetParseError() const; size_t GetErrorOffset() const; operator ParseResult() const;
    Allocator& GetAllocator(); size_t GetStackCapacity() const;
    bool Null(); bool Bool(bool b); bool Int(int i); bool Uint(unsigned i); bool Int64(int64_t i); bool Uint64(uint64_t i); bool Double(double d);
    bool RawNumber(const Ch* str, SizeType length, bool copy);
    bool String(const Ch* str, SizeType length, bool copy);
    bool StartObject(); bool Key(const Ch* str, SizeType length, bool copy); bool EndObject(SizeType memberCount);
    bool StartArray(); bool EndArray(SizeType elementCount);
private:
    GenericDocument(const GenericDocument&);
    GenericDocument& operator=(const GenericDocument&);
    void ClearStack(); void Destroy();
    static const size_t kDefaultStackCapacity = 1024;
    Allocator* allocator_; Allocator* ownAllocator_;
    internal::Stack<StackAllocator> stack_;
    ParseResult parseResult_;
};

typedef GenericDocument<UTF8<> > Document;

class ISchemaValidator {
public:
    virtual ~ISchemaValidator() {}
    virtual bool IsValid() const = 0;
    virtual void SetValidateFlags(unsigned flags) = 0;
    virtual unsigned GetValidateFlags() const = 0;
};

