// Generate a small positive allocation size to avoid NULL-by-contract on size==0.
size_t size = (size_t)(*FUZZ_PARAM(unsigned int) % 1024u) + 1u;
rapidjson::CrtAllocator crt;
void* p = crt.Malloc(size);
// If allocation fails (OOM), bail to avoid emitting a NULL output pointer.
if (!p) { FUZZ_BAIL(); }
// Tag the allocation so downstream Free/Realloc can validate allocator compatibility.
FUZZ_SET_ATTR_STR(p, "alloc", "crt");
FUZZ_SET_ATTR_INT(p, "size", (int)size);
// Output the allocated pointer for later Free/Realloc.
void* ptr = p;

rapidjson::CrtAllocator crt;
// Create an initial allocation (non-zero) to grow/shrink.
size_t oldSize = (size_t)(*FUZZ_PARAM(unsigned int) % 512u) + 1u;
void* orig = crt.Malloc(oldSize);
if (!orig) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_STR(orig, "alloc", "crt");
FUZZ_SET_ATTR_INT(orig, "size", (int)oldSize);
// Choose a new size (non-zero) so Realloc should return a non-NULL pointer on success.
size_t newSize = (size_t)(*FUZZ_PARAM(unsigned int) % 1024u) + 1u;
void* np = crt.Realloc(orig, oldSize, newSize);
if (!np) {
    // Realloc failed: original remains valid; free it to avoid leaking, then bail (no NULL outputs allowed).
    rapidjson::CrtAllocator::Free(orig);
    FUZZ_BAIL();
}
// Tag the new pointer for downstream validation and output it.
FUZZ_SET_ATTR_STR(np, "alloc", "crt");
FUZZ_SET_ATTR_INT(np, "size", (int)newSize);
void* ptr = np;

// Ensure the pointer came from CrtAllocator::Malloc/Realloc.
const char* kind = FUZZ_GET_ATTR_STR(ptr, "alloc");
if (!kind || kind[0] == '\0' || strcmp(kind, "crt") != 0) { FUZZ_BAIL(); }
rapidjson::CrtAllocator::Free(ptr);
// Dropping ptr; do not return it as an output.

// CrtAllocator is stateless; all instances compare equal.
