bool eq = (a == b);
FUZZ_ASSERT(eq, "CrtAllocator::operator== must always return true");

// CrtAllocator is stateless; no two instances are unequal.
rapidjson::CrtAllocator a, b;
bool ne = (a != b);
FUZZ_ASSERT(!ne, "CrtAllocator::operator!= must always return false");

// Construct a MemoryPoolAllocator with internal (owned) BaseAllocator by passing NULL.
