rapidjson::MemoryPoolAllocator<>* a = new rapidjson::MemoryPoolAllocator<>(chunkCap, (rapidjson::CrtAllocator*)0);
// Tag and output opaque pointer for subsequent stubs.
void* mpa = (void*)a;
FUZZ_SET_ATTR_STR(mpa, "type", "mpa");
FUZZ_SET_ATTR_INT(mpa, "alive", 1);
FUZZ_SET_ATTR_INT(mpa, "chunk", (int)chunkCap);

