import random
import struct
import itertools

# Generator for arbitrary binary data tailored to RapidJSON stream/encoding stubs.
# We prefer producing valid or near-valid sequences for various encodings while
# also mixing edge cases (empty, short, BOM-prefixed, mixed whitespace, JSON snippets, etc.).

MAX_LEN = 4096

ASCII_WHITESPACE = b" \t\r\n"
JSON_LITERALS = [b"null", b"true", b"false"]
JSON_NUMBERS = [b"0", b"-0", b"1", b"-1", b"123", b"-123", b"3.14", b"-2.5", b"1e10", b"-1E-5"]
JSON_TOKENS = [b"{}", b"[]", b"{\"a\":1}", b"{\"k\":[1,2,3]}", b"{\"s\":\"x\"}", b"{\"b\":true}", b"{\"n\":null}"]

# Common BOMs
BOM_UTF8 = b"\xEF\xBB\xBF"
BOM_UTF16LE = b"\xFF\xFE"
BOM_UTF16BE = b"\xFE\xFF"
BOM_UTF32LE = b"\xFF\xFE\x00\x00"
BOM_UTF32BE = b"\x00\x00\xFE\xFF"

# Helpers to build valid UTF sequences

def gen_utf8_codepoint(rng):
    # Select ranges: ASCII, 2-byte, 3-byte (BMP not surrogates), 4-byte (planes)
    t = rng.choices([1,2,3,4], weights=[5,3,3,2])[0]
    if t == 1:
        cp = rng.randint(0x00, 0x7F)
    elif t == 2:
        cp = rng.randint(0x80, 0x7FF)
    elif t == 3:
        # avoid surrogates 0xD800-0xDFFF
        while True:
            cp = rng.randint(0x800, 0xFFFF)
            if not (0xD800 <= cp <= 0xDFFF):
                break
    else:
        cp = rng.randint(0x10000, 0x10FFFF)
    return cp

def encode_utf8(cp):
    if cp <= 0x7F:
        return bytes([cp])
    elif cp <= 0x7FF:
        return bytes([0xC0 | (cp >> 6), 0x80 | (cp & 0x3F)])
    elif cp <= 0xFFFF:
        return bytes([0xE0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3F), 0x80 | (cp & 0x3F)])
    else:
        return bytes([0xF0 | (cp >> 18), 0x80 | ((cp >> 12) & 0x3F), 0x80 | ((cp >> 6) & 0x3F), 0x80 | (cp & 0x3F)])

def gen_valid_utf8(rng, target_len):
    out = bytearray()
    # Optional BOM
    if rng.random() < 0.2:
        out += BOM_UTF8
    while len(out) < target_len:
        out += encode_utf8(gen_utf8_codepoint(rng))
        if len(out) > target_len:
            break
    return bytes(out[:target_len])

# UTF-16 generators

def gen_utf16le_units(rng, units):
    arr = []
    for _ in range(units):
        # generate BMP non-surrogate most times, sometimes surrogate pair
        if rng.random() < 0.2:
            # produce surrogate pair (valid if paired)
            high = rng.randint(0xD800, 0xDBFF)
            low = rng.randint(0xDC00, 0xDFFF)
            arr.extend([high, low])
        else:
            v = rng.randint(0x0000, 0xD7FF)
            arr.append(v)
    # encode LE
    b = bytearray()
    for u in arr:
        b += struct.pack('<H', u)
    return bytes(b)

def gen_utf16be_units(rng, units):
    arr = []
    for _ in range(units):
        if rng.random() < 0.2:
            high = rng.randint(0xD800, 0xDBFF)
            low = rng.randint(0xDC00, 0xDFFF)
            arr.extend([high, low])
        else:
            v = rng.randint(0x0000, 0xD7FF)
            arr.append(v)
    b = bytearray()
    for u in arr:
        b += struct.pack('>H', u)
    return bytes(b)

# UTF-32 generators

def gen_utf32le_units(rng, units):
    b = bytearray()
    for _ in range(units):
        while True:
            cp = rng.randint(0, 0x10FFFF)
            if not (0xD800 <= cp <= 0xDFFF):
                break
        b += struct.pack('<I', cp)
    return bytes(b)

def gen_utf32be_units(rng, units):
    b = bytearray()
    for _ in range(units):
        while True:
            cp = rng.randint(0, 0x10FFFF)
            if not (0xD800 <= cp <= 0xDFFF):
                break
        b += struct.pack('>I', cp)
    return bytes(b)

# JSON builder focused on valid small documents

def gen_small_json(rng, budget):
    # Assemble a small but valid JSON string within budget
    choices = []
    choices.extend(JSON_TOKENS)
    choices.extend(JSON_LITERALS)
    choices.extend(JSON_NUMBERS)
    # Random string with escapes
    s_len = rng.randint(0, max(0, min(16, budget//2)))
    s = ''.join(chr(rng.randint(32, 126)) for _ in range(s_len))
    s = s.replace('"', '\\"').replace('\\', '\\\\')
    choices.append(('"' + s + '"').encode('utf-8'))
    # Simple object or array composed from tokens
    arr = b"[" + b",".join(rng.choices(choices, k=rng.randint(0,3))) + b"]"
    obj = b"{\"k\":" + rng.choice(choices) + b"}"
    pool = choices + [arr, obj]
    out = rng.choice(pool)
    return out[:budget]

# Prefix builder for whitespace / BOM / mix

def maybe_prefix(rng):
    parts = []
    # Optional whitespace prefix
    if rng.random() < 0.6:
        n = rng.randint(0, 32)
        parts.append(bytes(rng.choice(ASCII_WHITESPACE) for _ in range(n)))
    # Optional BOM of a random type
    if rng.random() < 0.3:
        parts.append(rng.choice([BOM_UTF8, BOM_UTF16LE, BOM_UTF16BE, BOM_UTF32LE, BOM_UTF32BE]))
    return b"".join(parts)

# Filename bytes: produce plausible small ASCII path with directories and extension

def gen_filename_bytes(rng, budget):
    # Keep within typical filesystem safe ASCII
    components = []
    depth = rng.randint(0, 3)
    for _ in range(depth):
        name_len = rng.randint(1, 8)
        name = bytes(rng.choice(b"abcdefghijklmnopqrstuvwxyz0123456789_-") for _ in range(name_len))
        components.append(name)
    base_len = rng.randint(1, 8)
    base = bytes(rng.choice(b"abcdefghijklmnopqrstuvwxyz0123456789_-") for _ in range(base_len))
    ext = rng.choice([b".txt", b".json", b".dat", b".bin", b".tmp"]) if rng.random()<0.8 else b""
    path = b"/".join(components + [base + ext]) if components else base + ext
    if rng.random() < 0.2:
        path = b"/tmp/" + path
    return path[:budget]

# Main strategy mixer

def build_buffer(rng, max_len):
    # Choose a scenario matching the fuzzer stubs use-cases
    scenario = rng.choices(
        [
            'utf8', 'utf8_bom', 'utf16le', 'utf16be', 'utf32le', 'utf32be',
            'ascii', 'json', 'json_ws', 'filename', 'mixed', 'tiny', 'empty'
        ],
        weights=[
            12, 4, 6, 6, 4, 4,
            6, 14, 10, 4, 10, 6, 4
        ]
    )[0]

    budget = rng.randint(1, max(1, min(256, max_len)))

    if scenario == 'empty':
        return b""

    if scenario == 'tiny':
        n = rng.randint(1, min(8, max_len))
        return bytes(rng.getrandbits(8) for _ in range(n))

    if scenario == 'filename':
        return gen_filename_bytes(rng, min(budget, max_len))

    if scenario == 'json':
        return gen_small_json(rng, min(budget, max_len))

    if scenario == 'json_ws':
        core = gen_small_json(rng, min(budget, max_len))
        pref = maybe_prefix(rng)
        out = pref + core
        return out[:max_len]

    if scenario == 'ascii':
        n = min(budget, max_len)
        # Mostly ASCII <= 0x7F
        return bytes(rng.randint(0x00 if rng.random()<0.1 else 0x20, 0x7F) for _ in range(n))

    if scenario == 'utf8' or scenario == 'utf8_bom':
        n = min(budget, max_len)
        core = gen_valid_utf8(rng, max(1, n - (3 if scenario=='utf8_bom' else 0)))
        if scenario == 'utf8_bom':
            return (BOM_UTF8 + core)[:max_len]
        return core

    if scenario == 'utf16le':
        # prepend LE BOM sometimes; keep even byte length
        units = max(1, min(32, budget // 2))
        body = gen_utf16le_units(rng, units)
        if rng.random() < 0.5:
            body = BOM_UTF16LE + body
        return body[:max_len]

    if scenario == 'utf16be':
        units = max(1, min(32, budget // 2))
        body = gen_utf16be_units(rng, units)
        if rng.random() < 0.5:
            body = BOM_UTF16BE + body
        return body[:max_len]

    if scenario == 'utf32le':
        units = max(1, min(16, budget // 4))
        body = gen_utf32le_units(rng, units)
        if rng.random() < 0.5:
            body = BOM_UTF32LE + body
        return body[:max_len]

    if scenario == 'utf32be':
        units = max(1, min(16, budget // 4))
        body = gen_utf32be_units(rng, units)
        if rng.random() < 0.5:
            body = BOM_UTF32BE + body
        return body[:max_len]

    # mixed: combine whitespace/BOM + utf8/json chunks
    pref = maybe_prefix(rng)
    chunk1 = gen_valid_utf8(rng, rng.randint(1, min(64, max_len)))
    if rng.random() < 0.5:
        chunk2 = gen_small_json(rng, rng.randint(1, min(128, max_len)))
    else:
        chunk2 = gen_valid_utf8(rng, rng.randint(1, min(64, max_len)))
    out = pref + chunk1 + (b"\n" if rng.random()<0.5 else b" ") + chunk2
    return out[:max_len]


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    data = build_buffer(rng, MAX_LEN)
    # Ensure at most 4096 bytes
    return data[:MAX_LEN]
